mapper.select:
SELECT  FROM content_safety_recheck
WHERE state = 0 AND next_attempt_at <= #{now}
ORDER BY next_attempt_at, id
LIMIT #{limit}

mapper.update:
UPDATE content_safety_recheck
SET attempt_count = #{attemptCount}, next_attempt_at = #{nextAttemptAt}, last_error_code = #{errorCode},
    update_time = #{now}
WHERE id = #{id} AND state = 0 AND attempt_count = #{expectedAttempt}

UPDATE content_safety_recheck
SET state = #{state}, last_error_code = #{errorCode}, update_time = #{now}
WHERE id = #{id} AND state = 0 AND attempt_count = #{expectedAttempt}
